--- a/src/agent-ui/plugins/thinking-indicator/index.tsx
+++ b/src/agent-ui/plugins/thinking-indicator/index.tsx
@@ -1,1 +1,12 @@
-
+import { ConversationThinkingIndicatorPlugin as Implementation } from '@za38.03/agent-ui-plugins/thinking-indicator';
+import type { ComponentProps } from 'react';
+import { usePluginRenderScope } from '@za38.03/agent-ui-plugins';
+
+export const ConversationThinkingIndicatorPlugin = (props: ComponentProps<typeof Implementation>) => {
+  const scope = usePluginRenderScope<Partial<ComponentProps<typeof Implementation>>>();
+  if (scope?.kind !== 'conversation.thinking-indicator') {
+    return null;
+  }
+  return <Implementation {...scope.value} {...props} />;
+};
+

--- a/src/agent-ui/plugins/thinking-indicator/definition.ts
+++ b/src/agent-ui/plugins/thinking-indicator/definition.ts
@@ -1,1 +1,12 @@
-
+import { type UIPluginDefinition } from '@za38.03/agent-ui-plugins';
+import implementation from '@za38.03/agent-ui-plugins/thinking-indicator';
+import { ConversationThinkingIndicatorPlugin } from './index';
+const definition: UIPluginDefinition = {
+  manifest: implementation.manifest,
+  provides: [],
+  inject: [],
+  optionalInject: [],
+  Component: ConversationThinkingIndicatorPlugin,
+};
+export default definition;
+
